package com.logiplatform.controller; import com.logiplatform.dto.PublicPortalDtos.PortalView; import com.logiplatform.service.PublicPortalService; import org.springframework.web.bind.annotation.*; import java.util.UUID; @RestController @RequestMapping("/api/public/portal") public class PublicPortalController{private final PublicPortalService service; public PublicPortalController(PublicPortalService s){service=s;} @GetMapping("/{token}") public PortalView get(@PathVariable UUID token){return service.find(token);}}